1	package main
2	
3	import (
4		"fmt"
5		"sort"
6	)
7	
8	// 周期保养计划与完成登记。
9	//
10	// 日期一律为 0001 至 9999 年的公历日历日（YYYY-MM-DD），按日历日运算：
11	// 不涉及时区与运行时刻，内部以“距 0001-01-01 的天数”做整数运算，避免
12	// time.Time 的时区、跨度（time.Duration 约 292 年上限）与年份范围问题。
13	//
14	// 每个计划恰有一条建立履历（含初始计划：内容、首次到期日、间隔天数），
15	// 每次完成登记追加一条完成履历（含周期到期日、实际完成日、结果），每次撤销
16	// 误登记追加一条撤销履历（含目标完成履历序号、理由），每次方案调整追加一条
17	// 调整履历（含前后方案、原下一到期日与理由）。建立与调整履历的全库序号把
18	// 保养历史划分为方案段：完成与撤销只作用于当时所在段，下一到期日按本段
19	// 首次日加整数倍间隔推进；计划保存的是当前段方案与由履历链推出的下一到期日，
20	// 加载与保存时核对二者一致。
21	// 保养不创建或终结工单、不消耗工单编号，不改变资产状态、请求绑定或停机统计。
22	
23	// Plan 为资产的周期保养计划；每项资产最多一个，不可覆盖，但可经调整履历
24	// 更换内容、周期起点与间隔。Content/FirstDue/IntervalDays 为当前方案段的
25	// 方案，NextDue 为由履历链推出的下一到期日，随每次完成登记推进、随撤销
26	// 回退、随调整重置为新首次到期日。
27	type Plan struct {
28		AssetID      string `json:"asset_id"`
29		Content      string `json:"content"`
30		FirstDue     string `json:"first_due"`
31		IntervalDays int    `json:"interval_days"`
32		NextDue      string `json:"next_due"`
33	}
34	
35	// maxDayNum 为 9999-12-31 的日序号（0001-01-01 为 0）。
36	const maxDayNum = 3652058
37	
38	// daysFromCivil 返回公历日期距 0001-01-01 的天数（该日为 0）。
39	// 输入须为 0001 至 9999 年间的有效日期（由 parseDate 保证）。
40	func daysFromCivil(y, m, d int) int64 {
41		yy := int64(y)
42		if m <= 2 {
43			yy--
44		}
45		era := yy / 400
46		yoe := yy - era*400
47		mp := int64((m + 9) % 12)
48		doy := (153*mp+2)/5 + int64(d) - 1
49		doe := yoe*365 + yoe/4 - yoe/100 + doy
50		return era*146097 + doe - 306
51	}
52	
53	// civilFromDays 为 daysFromCivil 的逆运算。
54	func civilFromDays(n int64) (int, int, int) {
55		z := n + 306
56		era := z / 146097
57		doe := z - era*146097
58		yoe := (doe - doe/1460 + doe/36524 - doe/146096) / 365
59		y := yoe + era*400
60		doy := doe - (365*yoe + yoe/4 - yoe/100)
61		mp := (5*doy + 2) / 153
62		d := doy - (153*mp+2)/5 + 1
63		if mp < 10 {
64			return int(y), int(mp + 3), int(d)
65		}
66		return int(y + 1), int(mp - 9), int(d)
67	}
68	
69	func isLeapYear(y int) bool {
70		return y%4 == 0 && (y%100 != 0 || y%400 == 0)
71	}
72	
73	func daysInMonth(y, m int) int {
74		switch m {
75		case 1, 3, 5, 7, 8, 10, 12:
76			return 31
77		case 4, 6, 9, 11:
78			return 30
79		}
80		if isLeapYear(y) {
81			return 29
82		}
83		return 28
84	}
85	
86	// atoiN 解析定长十进制数字串；含非数字字符时 ok=false。
87	func atoiN(s string) (int, bool) {
88		n := 0
89		for i := 0; i < len(s); i++ {
90			if s[i] < '0' || s[i] > '9' {
91				return 0, false
92			}
93			n = n*10 + int(s[i]-'0')
94		}
95		return n, true
96	}
97	
98	// parseDate 解析 YYYY-MM-DD 形式的公历日期（0001 至 9999 年，须为零填充的
99	// 完整形式），返回日序号。闰日等按公历规则校验。
100	func parseDate(s string) (int64, error) {
101		if len(s) != 10 || s[4] != '-' || s[7] != '-' {
102			return 0, fmt.Errorf("不是 YYYY-MM-DD 形式: %q", s)
103		}
104		y, ok1 := atoiN(s[0:4])
105		m, ok2 := atoiN(s[5:7])
106		d, ok3 := atoiN(s[8:10])
107		if !ok1 || !ok2 || !ok3 {
108			return 0, fmt.Errorf("不是 YYYY-MM-DD 形式: %q", s)
109		}
110		if y < 1 || m < 1 || m > 12 || d < 1 || d > daysInMonth(y, m) {
111			return 0, fmt.Errorf("不是 0001 至 9999 年间的有效公历日期: %q", s)
112		}
113		return daysFromCivil(y, m, d), nil
114	}
115	
116	// formatDate 把日序号格式化为 YYYY-MM-DD。
117	func formatDate(n int64) string {
118		y, m, d := civilFromDays(n)
119		return fmt.Sprintf("%04d-%02d-%02d", y, m, d)
120	}
121	
122	// nextDueAfter 返回首次到期日加整数倍间隔所得日期中，严格晚于 after 的最早
123	// 日期。结果超出 9999-12-31 时 ok=false。间隔必须为正整数。
124	func nextDueAfter(first, interval, after int64) (int64, bool) {
125		var k int64
126		if after >= first {
127			k = (after-first)/interval + 1
128		}
129		// k ≥ 1 且间隔本身已超出剩余日期范围时，结果必然越界；先判断避免溢出。
130		if k > 0 && interval > maxDayNum-first {
131			return 0, false
132		}
133		n := first + k*interval
134		if n > maxDayNum {
135			return 0, false
136		}
137		return n, true
138	}
139	
140	// findPlan 返回资产的保养计划，无计划时返回 nil。
141	func (s *store) findPlan(assetID string) *Plan {
142		for _, p := range s.data.Plans {
143			if p.AssetID == assetID {
144				return p
145			}
146		}
147		return nil
148	}
149	
150	// appendMaintEvent 以给定序号追加保养履历（建立或完成）。保养履历不属于任何
151	// 工单，from/to 恒为空；due/done/interval 按履历类型使用。
152	func (s *store) appendMaintEvent(seq int, assetID, kind, content, due, done string, interval int) {
153		s.data.Events = append(s.data.Events, Event{
154			Seq:      seq,
155			AssetID:  assetID,
156			Kind:     kind,
157			Content:  content,
158			Due:      due,
159			Done:     done,
160			Interval: interval,
161			Time:     s.now(),
162		})
163	}
164	
165	// createPlan 为资产建立唯一的周期保养计划：每项资产最多一个，已有计划时拒绝，
166	// 不覆盖。成功时追加一条含初始计划的建立履历，下一到期日即首次到期日。
167	// 失败路径不修改任何业务数据。
168	func (s *store) createPlan(assetID, content, firstDue string, intervalDays int) (*Plan, error) {
169		if s.findAsset(assetID) == nil {
170			return nil, fmt.Errorf("%w: 未知资产编号 %q", errNotFound, assetID)
171		}
172		if s.findPlan(assetID) != nil {
173			return nil, fmt.Errorf("%w: 资产 %s 已有保养计划，不能重复建立或覆盖", errConflict, assetID)
174		}
175		if content == "" {
176			return nil, fmt.Errorf("%w: 保养内容不能为空", errConflict)
177		}
178		if intervalDays < 1 {
179			return nil, fmt.Errorf("%w: 保养间隔天数须为正整数", errConflict)
180		}
181		if _, err := parseDate(firstDue); err != nil {
182			return nil, fmt.Errorf("%w: 首次到期日无效：%s", errConflict, err)
183		}
184		eventSeq, err := s.nextEventSeq()
185		if err != nil {
186			return nil, err
187		}
188		p := &Plan{
189			AssetID:      assetID,
190			Content:      content,
191			FirstDue:     firstDue,
192			IntervalDays: intervalDays,
193			NextDue:      firstDue,
194		}
195		s.data.Plans = append(s.data.Plans, p)
196		s.appendMaintEvent(eventSeq, assetID, eventPlanCreate, content, firstDue, "", intervalDays)
197		return p, nil
198	}
199	
200	// adjustPlan 调整已有计划的保养方案：更换内容、周期起点（新首次到期日）与
201	// 间隔，理由非空；仅已有计划的资产可调整，维修中、停用时也允许。新首次到期日
202	// 须严格晚于该资产所有未撤销完成（含调整前旧段）的实际完成日，没有有效完成
203	// 则无此限制。成功时追加一条记录前后方案、原下一到期日、理由与时间的资产级
204	// 调整履历，以该履历的全库序号开启新方案段：计划采用新方案，下一到期日设为
205	// 新首次到期日，不补任何完成记录，旧段完成不能再撤销。调整不改变资产状态、
206	// 工单、请求绑定或停机统计。失败路径不修改任何业务数据。
207	func (s *store) adjustPlan(assetID, content, firstDue string, intervalDays int, reason string) (*Plan, *Plan, error) {
208		if s.findAsset(assetID) == nil {
209			return nil, nil, fmt.Errorf("%w: 未知资产编号 %q", errNotFound, assetID)
210		}
211		p := s.findPlan(assetID)
212		if p == nil {
213			return nil, nil, fmt.Errorf("%w: 资产 %s 没有保养计划，不能调整", errNotFound, assetID)
214		}
215		if content == "" {
216			return nil, nil, fmt.Errorf("%w: 保养内容不能为空", errConflict)
217		}
218		if reason == "" {
219			return nil, nil, fmt.Errorf("%w: 调整理由不能为空", errConflict)
220		}
221		if intervalDays < 1 {
222			return nil, nil, fmt.Errorf("%w: 保养间隔天数须为正整数", errConflict)
223		}
224		firstN, err := parseDate(firstDue)
225		if err != nil {
226			return nil, nil, fmt.Errorf("%w: 新首次到期日无效：%s", errConflict, err)
227		}
228		// 新首次到期日须严格晚于所有未撤销完成的实际完成日（跨全部方案段）。
229		revoked := s.revokedDoneSeqs()
230		latestDone := int64(-1)
231		for _, e := range s.data.Events {
232			if e.AssetID != assetID || e.Kind != eventPlanDone || revoked[e.Seq] {
233				continue
234			}
235			doneN, _ := parseDate(e.Done)
236			if doneN > latestDone {
237				latestDone = doneN
238			}
239		}
240		if latestDone >= 0 && firstN <= latestDone {
241			return nil, nil, fmt.Errorf(
242				"%w: 新首次到期日 %s 须严格晚于资产 %s 未撤销完成的实际完成日 %s",
243				errConflict, firstDue, assetID, formatDate(latestDone))
244		}
245		eventSeq, err := s.nextEventSeq()
246		if err != nil {
247			return nil, nil, err
248		}
249		old := *p
250		s.data.Events = append(s.data.Events, Event{
251			Seq:         eventSeq,
252			AssetID:     assetID,
253			Kind:        eventPlanAdjust,
254			Content:     reason,
255			Due:         firstDue,
256			Interval:    intervalDays,
257			NewContent:  content,
258			OldContent:  old.Content,
259			OldDue:      old.FirstDue,
260			OldInterval: old.IntervalDays,
261			OldNextDue:  old.NextDue,
262			Time:        s.now(),
263		})
264		p.Content = content
265		p.FirstDue = firstDue
266		p.IntervalDays = intervalDays
267		p.NextDue = firstDue
268		return p, &old, nil
269	}
270	
271	// completePlan 登记当前方案段下一周期的保养完成：所填到期日必须等于当前下一
272	// 到期日（旧周期不能重复登记，也不能登记尚未到期的新周期），实际完成日不得早于
273	// 周期到期日。成功时追加一条完成履历，并把下一到期日推进到本段首次到期日加
274	// 整数倍间隔所得日期中严格晚于完成日的最早日期；延期跨过的周期不生成完成记录。
275	// 若下一到期日超出 9999-12-31，整次拒绝。返回完成履历的全库序号。
276	// 失败路径不修改任何业务数据。
277	func (s *store) completePlan(assetID, due, done, result string) (*Plan, string, int, error) {
278		if s.findAsset(assetID) == nil {
279			return nil, "", 0, fmt.Errorf("%w: 未知资产编号 %q", errNotFound, assetID)
280		}
281		p := s.findPlan(assetID)
282		if p == nil {
283			return nil, "", 0, fmt.Errorf("%w: 资产 %s 没有保养计划", errNotFound, assetID)
284		}
285		if a := s.findAsset(assetID); a != nil && a.Status == statusDeactivated {
286			// 停用期间拒绝保养完成登记；停用不暂停或重算周期，保存的下一到期日不变。
287			return nil, "", 0, fmt.Errorf("%w: 资产 %s 已停用，不能登记保养完成", errConflict, assetID)
288		}
289		if result == "" {
290			return nil, "", 0, fmt.Errorf("%w: 保养结果不能为空", errConflict)
291		}
292		dueN, err := parseDate(due)
293		if err != nil {
294			return nil, "", 0, fmt.Errorf("%w: 周期到期日无效：%s", errConflict, err)
295		}
296		doneN, err := parseDate(done)
297		if err != nil {
298			return nil, "", 0, fmt.Errorf("%w: 实际完成日无效：%s", errConflict, err)
299		}
300		if due != p.NextDue {
301			return nil, "", 0, fmt.Errorf(
302				"%w: 周期到期日 %s 与资产 %s 当前下一到期日 %s 不符（旧周期不能重复登记，也不能登记新周期）",
303				errConflict, due, assetID, p.NextDue)
304		}
305		if doneN < dueN {
306			return nil, "", 0, fmt.Errorf("%w: 实际完成日 %s 早于周期到期日 %s", errConflict, done, due)
307		}
308		first, _ := parseDate(p.FirstDue)
309		next, ok := nextDueAfter(first, int64(p.IntervalDays), doneN)
310		if !ok {
311			return nil, "", 0, fmt.Errorf(
312				"%w: 按完成日 %s 推算的下一到期日超出 9999-12-31，无法登记本次完成", errConflict, done)
313		}
314		eventSeq, err := s.nextEventSeq()
315		if err != nil {
316			return nil, "", 0, err
317		}
318		p.NextDue = formatDate(next)
319		s.appendMaintEvent(eventSeq, assetID, eventPlanDone, result, due, done, 0)
320		return p, p.NextDue, eventSeq, nil
321	}
322	
323	// revokedDoneSeqs 返回已被撤销的保养完成履历序号集合。
324	func (s *store) revokedDoneSeqs() map[int]bool {
325		revoked := map[int]bool{}
326		for _, e := range s.data.Events {
327			if e.Kind == eventPlanRevoke {
328				revoked[e.TargetSeq] = true
329			}
330		}
331		return revoked
332	}
333	
334	// currentSegmentStart 返回资产当前方案段的起点：该资产最近一次保养建立或
335	// 调整履历的全库序号；没有保养履历时为 0。段边界按全库履历序号划分，不按
336	// 日期或数组位置。
337	func (s *store) currentSegmentStart(assetID string) int {
338		start := 0
339		for _, e := range s.data.Events {
340			if e.AssetID == assetID && (e.Kind == eventPlanCreate || e.Kind == eventPlanAdjust) && e.Seq > start {
341				start = e.Seq
342			}
343		}
344		return start
345	}
346	
347	// revokeCompletion 撤销误登记的保养完成：目标须为该资产当前方案段内按序号最新
348	// 的未撤销完成（存在更晚有效完成时拒绝；撤销后可继续撤销本段此前最新有效完成；
349	// 调整前旧段的完成不能再撤销）。成功时保留原完成的日期、结果与时间，追加一条
350	// 含目标序号、理由与操作时间的撤销履历，并把下一到期日恢复为该完成的周期到期日
351	// （延期跨过的周期不补记录）。维修或其他资产事件不阻止撤销。失败路径不修改任何
352	// 业务数据。
353	func (s *store) revokeCompletion(assetID string, targetSeq int, reason string) (*Plan, *Event, error) {
354		if s.findAsset(assetID) == nil {
355			return nil, nil, fmt.Errorf("%w: 未知资产编号 %q", errNotFound, assetID)
356		}
357		if reason == "" {
358			return nil, nil, fmt.Errorf("%w: 撤销理由不能为空", errConflict)
359		}
360		p := s.findPlan(assetID)
361		if p == nil {
362			return nil, nil, fmt.Errorf("%w: 资产 %s 没有保养计划", errNotFound, assetID)
363		}
364		var target *Event
365		for i := range s.data.Events {
366			if s.data.Events[i].Seq == targetSeq {
367				target = &s.data.Events[i]
368				break
369			}
370		}
371		if target == nil {
372			return nil, nil, fmt.Errorf("%w: 未知履历序号 %d", errNotFound, targetSeq)
373		}
374		if target.Kind != eventPlanDone || target.AssetID != assetID {
375			return nil, nil, fmt.Errorf("%w: 履历序号 %d 不是资产 %s 的保养完成履历", errConflict, targetSeq, assetID)
376		}
377		segStart := s.currentSegmentStart(assetID)
378		if target.Seq < segStart {
379			return nil, nil, fmt.Errorf(
380				"%w: 完成履历序号 %d 属于资产 %s 调整前的旧方案段，旧段完成不能再撤销",
381				errConflict, targetSeq, assetID)
382		}
383		revoked := s.revokedDoneSeqs()
384		if revoked[targetSeq] {
385			return nil, nil, fmt.Errorf("%w: 完成履历序号 %d 已撤销，不能重复撤销", errConflict, targetSeq)
386		}
387		latest := 0
388		for _, e := range s.data.Events {
389			if e.AssetID == assetID && e.Kind == eventPlanDone && e.Seq > segStart && !revoked[e.Seq] && e.Seq > latest {
390				latest = e.Seq
391			}
392		}
393		if latest != targetSeq {
394			return nil, nil, fmt.Errorf(
395				"%w: 完成履历序号 %d 不是资产 %s 当前方案段最新的有效完成（当前为序号 %d），存在更晚有效完成时不能撤销",
396				errConflict, targetSeq, assetID, latest)
397		}
398		eventSeq, err := s.nextEventSeq()
399		if err != nil {
400			return nil, nil, err
401		}
402		p.NextDue = target.Due
403		s.data.Events = append(s.data.Events, Event{
404			Seq:       eventSeq,
405			AssetID:   assetID,
406			Kind:      eventPlanRevoke,
407			Content:   reason,
408			TargetSeq: targetSeq,
409			Time:      s.now(),
410		})
411		return p, target, nil
412	}
413	
414	// duePlanRow 为到期查询的一行结果。
415	type duePlanRow struct {
416		AssetID string
417		Name    string
418		Content string
419		Due     string
420	}
421	
422	// duePlans 列出下一到期日不晚于 date 的保养计划，按到期日再按资产编号排序。
423	// 停用资产不参与到期查询：停用不暂停或重算周期，保存的下一到期日保持不变，
424	// 恢复使用后仍按该日期参与查询，逾期计划显示原到期日。
425	// 只读：不写文件、不初始化目录、不推进计划。date 须为有效日期（调用方校验）。
426	func (s *store) duePlans(date string) []duePlanRow {
427		rows := make([]duePlanRow, 0)
428		for _, p := range s.data.Plans {
429			// YYYY-MM-DD 零填充形式的字典序即时间顺序。
430			if p.NextDue > date {
431				continue
432			}
433			a := s.findAsset(p.AssetID)
434			if a == nil {
435				continue // 整库一致性检查已保证归属；防御性跳过
436			}
437			if a.Status == statusDeactivated {
438				continue
439			}
440			rows = append(rows, duePlanRow{AssetID: p.AssetID, Name: a.Name, Content: p.Content, Due: p.NextDue})
441		}
442		sort.Slice(rows, func(i, j int) bool {
443			if rows[i].Due != rows[j].Due {
444				return rows[i].Due < rows[j].Due
445			}
446			return rows[i].AssetID < rows[j].AssetID
447		})
448		return rows
449	}
