54	// Asset 为登记的设备资产，ID 即企业资产编号。
55	type Asset struct {
56		ID       string `json:"id"`
57		Name     string `json:"name"`
58		Location string `json:"location"`
59		Status   string `json:"status"`
60	}
61	
62	// Ticket 为维修工单。Assignee 为当前（或终结前最后）负责人，空表示未派工；
63	// AssignedAt/AssignNote 为最近一次派工的变更时间与说明。
64	type Ticket struct {
65		ID           string `json:"id"`
66		AssetID      string `json:"asset_id"`
67		Description  string `json:"description"`
68		RequestID    string `json:"request_id"`
69		Status       string `json:"status"`
70		Result       string `json:"result,omitempty"`
71		CreatedAt    string `json:"created_at"`
72		ClosedAt     string `json:"closed_at,omitempty"`
73		CancelReason string `json:"cancel_reason,omitempty"`
74		CancelledAt  string `json:"cancelled_at,omitempty"`
75		Assignee     string `json:"assignee,omitempty"`
76		AssignedAt   string `json:"assigned_at,omitempty"`
77		AssignNote   string `json:"assign_note,omitempty"`
78	}
79	
80	// Event 为履历条目（报修/派工/关闭/取消/停用/恢复使用/保养建立/保养完成/保养撤销/保养调整/领用/退回/附件登记/附件撤销），Seq 决定操作发生顺序。
81	// From/To 在派工履历中为原负责人（首次派工为空，展示为“未派工”）与新负责人；
82	// 在停用、恢复使用履历中为原资产状态与新资产状态。
83	// Due/Done/Interval 仅保养履历使用：建立履历含首次到期日（Due）与间隔天数
84	// （Interval），完成履历含周期到期日（Due）与实际完成日（Done）。
85	// TargetSeq 仅保养撤销履历使用：被撤销的完成履历的全库序号；完成身份以此序号
86	// 标识，不能用到期日或报修请求标识代替。
87	// 保养调整履历中 Content 为调整理由，Due/Interval 为新方案的首次到期日与间隔
88	// 天数，NewContent 为新保养内容，OldContent/OldDue/OldInterval 为原方案的内容、
89	// 首次到期日与间隔天数，OldNextDue 为调整前的下一到期日；调整以该履历的全库
90	// 序号划分方案段，不按日期或数组位置。
91	// PartID/Quantity/WithdrawalID 仅备件履历使用：领用与退回履历都携带备件编号、
92	// 数量与所属领用编号；Content 分别为领用说明与退回理由。
93	// AttachmentID/Path 仅附件履历使用：登记与撤销履历都携带附件编号与保存的绝对
94	// 路径；Content 分别为附件说明与撤销理由。
95	type Event struct {
96		Seq          int       `json:"-"`
97		AssetID      string    `json:"-"`
98		TicketID     string    `json:"-"`
99		Kind         string    `json:"-"`
100		Content      string    `json:"-"`
101		From         string    `json:"-"`
102		To           string    `json:"-"`
103		Due          string    `json:"-"`
104		Done         string    `json:"-"`
105		Interval     int       `json:"-"`
106		TargetSeq    int       `json:"-"`
107		NewContent   string    `json:"-"`
108		OldContent   string    `json:"-"`
109		OldDue       string    `json:"-"`
110		OldInterval  int       `json:"-"`
111		OldNextDue   string    `json:"-"`
112		PartID       string    `json:"-"`
113		Quantity     int       `json:"-"`
114		WithdrawalID string    `json:"-"`
115		AttachmentID string    `json:"-"`
116		Path         string    `json:"-"`
117		Time         time.Time `json:"-"`
118	}
119	
120	// eventJSON 与 Event 对应，时间以 RFC3339 文本持久化。
121	type eventJSON struct {
122		Seq          int    `json:"seq"`
123		AssetID      string `json:"asset_id"`
124		TicketID     string `json:"ticket_id,omitempty"`
125		Kind         string `json:"kind"`
126		Content      string `json:"content"`
127		From         string `json:"from,omitempty"`
128		To           string `json:"to,omitempty"`
129		Due          string `json:"due,omitempty"`
130		Done         string `json:"done,omitempty"`
131		Interval     int    `json:"interval,omitempty"`
132		TargetSeq    int    `json:"target_seq,omitempty"`
133		NewContent   string `json:"new_content,omitempty"`
134		OldContent   string `json:"old_content,omitempty"`
135		OldDue       string `json:"old_due,omitempty"`
136		OldInterval  int    `json:"old_interval,omitempty"`
137		OldNextDue   string `json:"old_next_due,omitempty"`
138		PartID       string `json:"part_id,omitempty"`
139		Quantity     int    `json:"quantity,omitempty"`
140		WithdrawalID string `json:"withdrawal_id,omitempty"`
141		AttachmentID string `json:"attachment_id,omitempty"`
142		Path         string `json:"path,omitempty"`
143		Time         string `json:"time"`
144	}
145	
146	func (e Event) toJSON() eventJSON {
147		return eventJSON{
148			Seq: e.Seq, AssetID: e.AssetID, TicketID: e.TicketID,
149			Kind: e.Kind, Content: e.Content, From: e.From, To: e.To,
150			Due: e.Due, Done: e.Done, Interval: e.Interval, TargetSeq: e.TargetSeq,
151			NewContent: e.NewContent, OldContent: e.OldContent,
152			OldDue: e.OldDue, OldInterval: e.OldInterval, OldNextDue: e.OldNextDue,
153			PartID: e.PartID, Quantity: e.Quantity, WithdrawalID: e.WithdrawalID,
154			AttachmentID: e.AttachmentID, Path: e.Path,
155			// RFC3339Nano 保留小数秒精度；整秒时输出与 RFC3339 完全一致，
156			// 因此既有整秒台账的字节表示不变，而旧库中带小数秒的履历时间
157			// 在重新保存（含导入合并后的提交）时也不会被截断。
158			Time: e.Time.Format(time.RFC3339Nano),
159		}
160	}
161	
162	func (e eventJSON) toEvent() (Event, error) {
163		t, err := time.Parse(time.RFC3339, e.Time)
164		if err != nil {
165			return Event{}, fmt.Errorf("履历时间格式无效 %q: %w", e.Time, err)
166		}
167		return Event{
168			Seq: e.Seq, AssetID: e.AssetID, TicketID: e.TicketID,
169			Kind: e.Kind, Content: e.Content, From: e.From, To: e.To,
170			Due: e.Due, Done: e.Done, Interval: e.Interval, TargetSeq: e.TargetSeq,
171			NewContent: e.NewContent, OldContent: e.OldContent,
172			OldDue: e.OldDue, OldInterval: e.OldInterval, OldNextDue: e.OldNextDue,
173			PartID: e.PartID, Quantity: e.Quantity, WithdrawalID: e.WithdrawalID,
174			AttachmentID: e.AttachmentID, Path: e.Path,
175			Time: t,
176		}, nil
177	}
