237	func newStoreData() *storeData {
238		return &storeData{
239			Version:       storeVersion,
240			Assets:        []*Asset{},
241			Tickets:       []*Ticket{},
242			Events:        []Event{},
243			EventsJSON:    []eventJSON{},
244			Requests:      []requestBinding{},
245			Plans:         []*Plan{},
246			Parts:         []*PartWithdrawal{},
247			Attachments:   []*Attachment{},
248			NextTicketSeq: 1,
249			NextPartSeq:   1,
250			NextAttachSeq: 1,
251		}
