876				}
877				if e.From != derivedAssignee[e.TicketID] {
878					return fmt.Errorf("履历矛盾：工单 %s 的派工履历（序号 %d）原负责人 %q 与上次记录不接续",
879						e.TicketID, e.Seq, e.From)
880				}
881				derivedAssignee[e.TicketID] = e.To
882				derivedNote[e.TicketID] = e.Content
883			case eventClose:
884				if derivedTicket[e.TicketID] != ticketOpen {
885					return fmt.Errorf("履历矛盾：工单 %s 在未处于未关闭状态时出现关闭履历", e.TicketID)
886				}
887				derivedTicket[e.TicketID] = ticketClosed
888				delete(derivedOpen, e.AssetID)
889			case eventCancel:
890				if derivedTicket[e.TicketID] != ticketOpen {
891					return fmt.Errorf("履历矛盾：工单 %s 在未处于未关闭状态时出现取消履历", e.TicketID)
892				}
893				derivedTicket[e.TicketID] = ticketCancelled
894				delete(derivedOpen, e.AssetID)
895			case eventPartWithdraw:
896				// 领用须在报修之后、终结之前；履历与领用记录的业务字段必须一致。
897				if derivedTicket[e.TicketID] != ticketOpen {
898					return fmt.Errorf("履历矛盾：工单 %s 在未处于未关闭状态时出现领用履历（序号 %d）",
899						e.TicketID, e.Seq)
900				}
901				p := parts[e.WithdrawalID]
902				if p == nil {
903					return fmt.Errorf("履历矛盾：领用履历（序号 %d）引用了不存在的领用记录 %s",
904						e.Seq, e.WithdrawalID)
905				}
906				if withdrawSeq[p.ID] != 0 {
907					return fmt.Errorf("履历矛盾：领用记录 %s 有多条领用履历", p.ID)
908				}
909				if p.TicketID != e.TicketID || p.AssetID != e.AssetID || p.PartID != e.PartID ||
910					p.Quantity != e.Quantity || p.Note != e.Content {
911					return fmt.Errorf("履历矛盾：领用履历（序号 %d）与领用记录 %s 的工单、资产、备件、数量或说明不一致",
912						e.Seq, p.ID)
913				}
914				withdrawSeq[p.ID] = e.Seq
915			case eventPartReturn:
916				// 退回须在报修之后、终结之前，且指向先前已领用的记录；
917				// 累计退回不得超过该笔原数量。
918				if derivedTicket[e.TicketID] != ticketOpen {
919					return fmt.Errorf("履历矛盾：工单 %s 在未处于未关闭状态时出现退回履历（序号 %d）",
920						e.TicketID, e.Seq)
921				}
922				p := parts[e.WithdrawalID]
923				if p == nil {
924					return fmt.Errorf("履历矛盾：退回履历（序号 %d）引用了不存在的领用记录 %s",
925						e.Seq, e.WithdrawalID)
926				}
927				if withdrawSeq[p.ID] == 0 {
928					return fmt.Errorf("履历矛盾：退回履历（序号 %d）出现在领用记录 %s 的领用履历之前",
929						e.Seq, p.ID)
930				}
931				if p.TicketID != e.TicketID || p.AssetID != e.AssetID || p.PartID != e.PartID {
932					return fmt.Errorf("履历矛盾：退回履历（序号 %d）与领用记录 %s 的工单、资产或备件不一致",
933						e.Seq, p.ID)
934				}
935				// 逐步核对累计退回不超过原数量：先做不会溢出的减法比较再累加。
936				// 直接相加可能整数溢出回绕，即使回绕后的累计恰好等于保存值，
937				// 实际超额的履历也必须拒绝。
938				if e.Quantity > p.Quantity-derivedReturned[p.ID] {
939					return fmt.Errorf("备件数量矛盾：领用记录 %s 的累计退回在履历序号 %d 处超过原数量 %d",
940						p.ID, e.Seq, p.Quantity)
941				}
942				derivedReturned[p.ID] += e.Quantity
943			case eventAttach:
944				// 登记须在报修之后；未关闭、已关闭或已取消工单均可补充资料。
945				// 履历与附件记录的业务字段必须一致。
946				if derivedTicket[e.TicketID] == "" {
947					return fmt.Errorf("履历矛盾：工单 %s 在报修之前出现附件登记履历（序号 %d）",
948						e.TicketID, e.Seq)
949				}
950				a := attachments[e.AttachmentID]
951				if a == nil {
952					return fmt.Errorf("履历矛盾：附件登记履历（序号 %d）引用了不存在的附件记录 %s",
953						e.Seq, e.AttachmentID)
954				}
955				if attachRegSeq[a.ID] != 0 {
956					return fmt.Errorf("履历矛盾：附件记录 %s 有多条登记履历", a.ID)
957				}
958				if a.TicketID != e.TicketID || a.AssetID != e.AssetID || a.Path != e.Path || a.Note != e.Content {
959					return fmt.Errorf("履历矛盾：附件登记履历（序号 %d）与附件记录 %s 的工单、资产、路径或说明不一致",
960						e.Seq, a.ID)
961				}
962				attachRegSeq[a.ID] = e.Seq
