967					return fmt.Errorf("履历矛盾：工单 %s 在报修之前出现附件撤销履历（序号 %d）",
968						e.TicketID, e.Seq)
969				}
970				a := attachments[e.AttachmentID]
971				if a == nil {
972					return fmt.Errorf("履历矛盾：附件撤销履历（序号 %d）引用了不存在的附件记录 %s",
973						e.Seq, e.AttachmentID)
974				}
975				if attachRegSeq[a.ID] == 0 {
976					return fmt.Errorf("履历矛盾：附件撤销履历（序号 %d）出现在附件记录 %s 的登记履历之前",
977						e.Seq, a.ID)
978				}
979				if attachRevokeSeq[a.ID] != 0 {
980					return fmt.Errorf("履历矛盾：附件记录 %s 有多条撤销履历", a.ID)
981				}
982				if a.TicketID != e.TicketID || a.AssetID != e.AssetID || a.Path != e.Path || a.RevokeReason != e.Content {
983					return fmt.Errorf("履历矛盾：附件撤销履历（序号 %d）与附件记录 %s 的工单、资产、路径或撤销理由不一致",
984						e.Seq, a.ID)
985				}
986				attachRevokeSeq[a.ID] = e.Seq
987			}
988		}
989		for _, t := range d.Tickets {
990			if derivedTicket[t.ID] != t.Status {
991				return fmt.Errorf("状态矛盾：按履历推进得到工单 %s 状态为 %s，与保存的 %s 不符",
992					t.ID, derivedTicket[t.ID], t.Status)
993			}
994			// 由履历推出的最后负责人须与工单记录一致；无派工履历则必须未派工。
995			if derivedAssignee[t.ID] != t.Assignee {
996				return fmt.Errorf("状态矛盾：按履历推出工单 %s 最后负责人为 %q，与保存的 %q 不符",
997					t.ID, derivedAssignee[t.ID], t.Assignee)
998			}
999			if t.Assignee != "" && derivedNote[t.ID] != t.AssignNote {
