1001			}
1002		}
1003		// 每笔领用记录恰有一条领用履历；按履历重放得到的累计退回须与保存值一致。
1004		for _, p := range d.Parts {
1005			if withdrawSeq[p.ID] == 0 {
1006				return fmt.Errorf("履历矛盾：领用记录 %s 缺少对应的领用履历", p.ID)
1007			}
1008			if derivedReturned[p.ID] != p.Returned {
1009				return fmt.Errorf("备件数量矛盾：按履历推出领用记录 %s 的累计退回为 %d，与保存的 %d 不符",
1010					p.ID, derivedReturned[p.ID], p.Returned)
1011			}
1012		}
1013		// 每条附件记录恰有一条登记履历、至多一条撤销履历；记录的撤销状态须与
1014		// 是否存在撤销履历一致。
1015		for _, a := range d.Attachments {
1016			if attachRegSeq[a.ID] == 0 {
1017				return fmt.Errorf("履历矛盾：附件记录 %s 缺少对应的登记履历", a.ID)
1018			}
1019			if revoked := attachRevokeSeq[a.ID] != 0; revoked != a.Revoked {
1020				return fmt.Errorf("状态矛盾：附件记录 %s 保存的撤销状态与履历不符", a.ID)
1021			}
1022		}
1023		for _, a := range d.Assets {
1024			want := statusAvailable
1025			switch {
1026			case derivedDeactivated[a.ID]:
1027				want = statusDeactivated
1028			case derivedOpen[a.ID] != "":
1029				want = statusRepairing
1030			}
1031			if a.Status != want {
1032				return fmt.Errorf("状态矛盾：按履历推进得到资产 %s 状态为 %s，与保存的 %s 不符",
1033					a.ID, want, a.Status)
1034			}
1035		}
