1053			}
1054			if _, err := parseDate(p.NextDue); err != nil {
1055				return fmt.Errorf("数据矛盾：资产 %s 保养计划的下一到期日无效", p.AssetID)
1056			}
1057			plans[p.AssetID] = p
1058		}
1059		// 保养履历链：每个计划恰有一条建立履历；建立与每次调整以各自的全库履历序号
1060		// 划分方案段（不按日期或数组位置），当前段方案为最近一次建立或调整记录的
1061		// 内容、首次到期日与间隔。完成履历按序号接续（周期到期日须等于当时下一
1062		// 到期日，完成日不早于它，按当时所在段的首次日加整数倍间隔推进），撤销履历
1063		// 须引用当时所在段内未撤销且最新有效的完成，并把下一到期日恢复为该完成的
1064		// 周期到期日；调整履历记录的原方案与原下一到期日须与当时状态一致，新首次
1065		// 到期日须严格晚于当时所有未撤销完成的实际完成日，调整后下一到期日即新
1066		// 首次到期日，旧段完成不能再撤销。由履历推出的当前方案与下一到期日须与
1067		// 计划保存的一致。没有计划的资产不得有保养履历。
1068		maintCreate := map[string]int{}
1069		derivedDue := map[string]string{}
1070		segContent := map[string]string{}
1071		segFirst := map[string]string{}
1072		segInterval := map[string]int{}
1073		doneSeqs := map[string][]int{}
1074		doneDue := map[string]map[int]string{}
1075		allDone := map[string]map[int]bool{}
1076		validDoneDay := map[string]map[int]int64{}
1077		revokedDone := map[int]bool{}
1078		// 停用状态随全库履历序号推进：停用期间不得登记保养完成；停用不暂停、不
1079		// 重算周期，因此建立、完成、撤销与调整的接续规则本身不受影响。
1080		deactivatedAt := map[string]bool{}
1081		for _, e := range sorted {
1082			switch e.Kind {
1083			case eventDeactivate:
1084				deactivatedAt[e.AssetID] = true
1085				continue
1086			case eventReactivate:
1087				delete(deactivatedAt, e.AssetID)
1088				continue
1089			}
1090			if e.Kind != eventPlanCreate && e.Kind != eventPlanDone && e.Kind != eventPlanRevoke && e.Kind != eventPlanAdjust {
1091				continue
1092			}
1093			p := plans[e.AssetID]
1094			if p == nil {
1095				return fmt.Errorf("履历矛盾：资产 %s 没有保养计划，却存在保养履历（序号 %d）", e.AssetID, e.Seq)
1096			}
1097			if e.Kind == eventPlanCreate {
1098				if maintCreate[e.AssetID] != 0 {
1099					return fmt.Errorf("履历矛盾：资产 %s 有多条保养建立履历", e.AssetID)
1100				}
1101				maintCreate[e.AssetID] = e.Seq
1102				segContent[e.AssetID] = e.Content
1103				segFirst[e.AssetID] = e.Due
1104				segInterval[e.AssetID] = e.Interval
1105				derivedDue[e.AssetID] = e.Due
1106				continue
1107			}
1108			if maintCreate[e.AssetID] == 0 {
1109				return fmt.Errorf("履历矛盾：资产 %s 的%s履历（序号 %d）出现在建立履历之前", e.AssetID, e.Kind, e.Seq)
1110			}
1111			if e.Kind == eventPlanAdjust {
1112				// 调整履历记录的原方案与原下一到期日须与当时状态一致；新首次到期日
1113				// 须严格晚于当时所有未撤销完成（含旧段）的实际完成日。调整后开启新
1114				// 方案段：下一到期日设为新首次到期日，旧段完成不能再撤销。
1115				if e.OldContent != segContent[e.AssetID] || e.OldDue != segFirst[e.AssetID] ||
1116					e.OldInterval != segInterval[e.AssetID] {
1117					return fmt.Errorf("履历矛盾：保养调整履历（序号 %d）记录的原方案与资产 %s 当时的方案不符",
1118						e.Seq, e.AssetID)
1119				}
1120				if e.OldNextDue != derivedDue[e.AssetID] {
1121					return fmt.Errorf("履历矛盾：保养调整履历（序号 %d）记录的原下一到期日 %s 与当时的下一到期日 %s 不符",
1122						e.Seq, e.OldNextDue, derivedDue[e.AssetID])
1123				}
1124				newFirst, _ := parseDate(e.Due)
1125				for doneSeq, doneDay := range validDoneDay[e.AssetID] {
1126					if newFirst <= doneDay {
1127						return fmt.Errorf("履历矛盾：保养调整履历（序号 %d）的新首次到期日 %s 未严格晚于未撤销完成（序号 %d）的实际完成日 %s",
1128							e.Seq, e.Due, doneSeq, formatDate(doneDay))
1129					}
1130				}
1131				segContent[e.AssetID] = e.NewContent
1132				segFirst[e.AssetID] = e.Due
1133				segInterval[e.AssetID] = e.Interval
1134				derivedDue[e.AssetID] = e.Due
1135				doneSeqs[e.AssetID] = nil
1136				doneDue[e.AssetID] = map[int]string{}
1137				continue
1138			}
1139			if e.Kind == eventPlanRevoke {
1140				// 目标须为当前段内先前的完成履历（更晚序号的完成此时尚未出现），
1141				// 未撤销且为当时最新有效；撤销后下一到期日恢复为其周期到期日。
1142				due, ok := doneDue[e.AssetID][e.TargetSeq]
1143				if !ok {
1144					if allDone[e.AssetID][e.TargetSeq] {
1145						return fmt.Errorf("履历矛盾：保养撤销履历（序号 %d）的目标序号 %d 属于资产 %s 调整前的旧方案段，旧段完成不能再撤销",
1146							e.Seq, e.TargetSeq, e.AssetID)
1147					}
1148					return fmt.Errorf("履历矛盾：保养撤销履历（序号 %d）的目标序号 %d 不是资产 %s 先前的完成履历",
1149						e.Seq, e.TargetSeq, e.AssetID)
1150				}
1151				if revokedDone[e.TargetSeq] {
1152					return fmt.Errorf("履历矛盾：完成履历序号 %d 被重复撤销（撤销履历序号 %d）", e.TargetSeq, e.Seq)
1153				}
1154				latest := 0
1155				for _, seq := range doneSeqs[e.AssetID] {
1156					if !revokedDone[seq] {
1157						latest = seq
1158					}
1159				}
1160				if latest != e.TargetSeq {
1161					return fmt.Errorf("履历矛盾：保养撤销履历（序号 %d）的目标序号 %d 不是当时最新的有效完成（序号 %d）",
1162						e.Seq, e.TargetSeq, latest)
1163				}
1164				revokedDone[e.TargetSeq] = true
1165				delete(validDoneDay[e.AssetID], e.TargetSeq)
1166				derivedDue[e.AssetID] = due
1167				continue
1168			}
1169			if e.Kind == eventPlanDone && deactivatedAt[e.AssetID] {
1170				return fmt.Errorf("履历矛盾：资产 %s 在停用期间出现保养完成履历（序号 %d）",
1171					e.AssetID, e.Seq)
1172			}
1173			if e.Due != derivedDue[e.AssetID] {
1174				return fmt.Errorf("履历矛盾：资产 %s 的保养完成履历（序号 %d）周期到期日 %s 与当前下一到期日 %s 不接续",
1175					e.AssetID, e.Seq, e.Due, derivedDue[e.AssetID])
1176			}
1177			first, _ := parseDate(segFirst[e.AssetID])
1178			done, _ := parseDate(e.Done)
1179			next, ok := nextDueAfter(first, int64(segInterval[e.AssetID]), done)
1180			if !ok {
1181				return fmt.Errorf("履历矛盾：资产 %s 的保养完成履历（序号 %d）无法推出日期范围内的下一到期日",
1182					e.AssetID, e.Seq)
1183			}
1184			derivedDue[e.AssetID] = formatDate(next)
1185			doneSeqs[e.AssetID] = append(doneSeqs[e.AssetID], e.Seq)
1186			if doneDue[e.AssetID] == nil {
1187				doneDue[e.AssetID] = map[int]string{}
1188			}
1189			doneDue[e.AssetID][e.Seq] = e.Due
1190			if allDone[e.AssetID] == nil {
1191				allDone[e.AssetID] = map[int]bool{}
1192			}
1193			allDone[e.AssetID][e.Seq] = true
1194			if validDoneDay[e.AssetID] == nil {
1195				validDoneDay[e.AssetID] = map[int]int64{}
1196			}
1197			validDoneDay[e.AssetID][e.Seq] = done
1198		}
1199		for _, p := range d.Plans {
1200			if maintCreate[p.AssetID] == 0 {
1201				return fmt.Errorf("履历矛盾：资产 %s 的保养计划应有恰一条建立履历，实际没有", p.AssetID)
1202			}
1203			if segContent[p.AssetID] != p.Content || segFirst[p.AssetID] != p.FirstDue || segInterval[p.AssetID] != p.IntervalDays {
1204				return fmt.Errorf("履历矛盾：按履历推出资产 %s 的当前方案（内容 %q、首次到期日 %s、每 %d 天）与保存的方案（内容 %q、首次到期日 %s、每 %d 天）不符",
1205					p.AssetID, segContent[p.AssetID], segFirst[p.AssetID], segInterval[p.AssetID],
1206					p.Content, p.FirstDue, p.IntervalDays)
1207			}
1208			if derivedDue[p.AssetID] != p.NextDue {
1209				return fmt.Errorf("履历矛盾：按履历推出资产 %s 的下一到期日为 %s，与保存的 %s 不符",
1210					p.AssetID, derivedDue[p.AssetID], p.NextDue)
1211			}
1212		}
1213		return nil
1214	}
1215	
1216	// save 将全部业务数据一次性原子写入：先写同目录临时文件，fsync 后 rename
1217	// 覆盖正式文件。写入前先校验待提交数据的一致性；校验或读写失败时原文件
1218	// 保持不变，不留下部分业务变化。
1219	func (s *store) save() error {
1220		s.data.EventsJSON = make([]eventJSON, len(s.data.Events))
1221		for i, e := range s.data.Events {
1222			s.data.EventsJSON[i] = e.toJSON()
1223		}
1224		if err := validateData(s.data); err != nil {
1225			return fmt.Errorf("待保存数据未通过一致性检查：%w（未写入任何数据）", err)
1226		}
1227		var buf bytes.Buffer
1228		enc := json.NewEncoder(&buf)
1229		enc.SetIndent("", "  ")
1230		if err := enc.Encode(s.data); err != nil {
1231			return fmt.Errorf("编码数据失败: %w", err)
1232		}
1233		if err := os.MkdirAll(s.dir, 0o755); err != nil {
1234			return fmt.Errorf("创建数据目录失败: %w", err)
1235		}
1236		path := filepath.Join(s.dir, dataFileName)
1237		tmp, err := os.CreateTemp(s.dir, ".caretrack-*.tmp")
1238		if err != nil {
1239			return fmt.Errorf("创建临时数据文件失败: %w", err)
1240		}
1241		tmpName := tmp.Name()
1242		abort := func(err error) error {
1243			_ = tmp.Close()
1244			_ = os.Remove(tmpName)
1245			return err
1246		}
1247		if _, err := tmp.Write(buf.Bytes()); err != nil {
1248			abort(nil)
1249			return fmt.Errorf("写入数据失败: %w", err)
1250		}
1251		if err := tmp.Sync(); err != nil {
1252			abort(nil)
1253			return fmt.Errorf("写入数据失败: %w", err)
1254		}
1255		if err := tmp.Close(); err != nil {
1256			_ = os.Remove(tmpName)
1257			return fmt.Errorf("写入数据失败: %w", err)
1258		}
1259		if err := os.Rename(tmpName, path); err != nil {
1260			_ = os.Remove(tmpName)
1261			return fmt.Errorf("保存数据失败: %w", err)
1262		}
1263		return nil
1264	}
1265	
1266	func (s *store) findAsset(id string) *Asset {
1267		for _, a := range s.data.Assets {
1268			if a.ID == id {
1269				return a
1270			}
1271		}
1272		return nil
1273	}
1274	
1275	func (s *store) findTicket(id string) *Ticket {
1276		for _, t := range s.data.Tickets {
1277			if t.ID == id {
1278				return t
1279			}
1280		}
1281		return nil
1282	}
1283	
1284	func (s *store) findRequest(requestID string) *requestBinding {
1285		for i := range s.data.Requests {
1286			if s.data.Requests[i].RequestID == requestID {
1287				return &s.data.Requests[i]
1288			}
1289		}
1290		return nil
1291	}
1292	
1293	func (s *store) openTicketOf(assetID string) *Ticket {
1294		for _, t := range s.data.Tickets {
1295			if t.AssetID == assetID && t.Status == ticketOpen {
1296				return t
1297			}
1298		}
1299		return nil
1300	}
1301	
1302	func (s *store) eventsOf(assetID string) []Event {
1303		out := make([]Event, 0)
1304		for _, e := range s.data.Events {
1305			if e.AssetID == assetID {
1306				out = append(out, e)
1307			}
1308		}
1309		sort.SliceStable(out, func(i, j int) bool { return out[i].Seq < out[j].Seq })
1310		return out
1311	}
1312	
1313	// nextEventSeq 返回下一条履历应使用的全库唯一正整数序号；计数器耗尽时报错。
1314	func (s *store) nextEventSeq() (int, error) {
1315		maxSeq := 0
1316		for _, e := range s.data.Events {
1317			if e.Seq > maxSeq {
1318				maxSeq = e.Seq
1319			}
1320		}
1321		if maxSeq == math.MaxInt {
1322			return 0, fmt.Errorf("%w: 履历序号计数器已耗尽，无法追加履历", errConflict)
1323		}
1324		return maxSeq + 1, nil
1325	}
1326	
1327	// appendEvent 以给定序号追加履历。调用方须先通过 nextEventSeq 取得序号，
1328	// 确保任何失败路径都不会在部分变更后才报错。from/to 仅派工履历使用。
1329	func (s *store) appendEvent(seq int, assetID, ticketID, kind, content, from, to string) {
1330		s.data.Events = append(s.data.Events, Event{
1331			Seq:      seq,
1332			AssetID:  assetID,
1333			TicketID: ticketID,
1334			Kind:     kind,
1335			Content:  content,
1336			From:     from,
1337			To:       to,
1338			Time:     s.now(),
1339		})
1340	}
1341	
1342	func (s *store) registerAsset(id, name, location string) (*Asset, error) {
1343		if s.findAsset(id) != nil {
1344			return nil, fmt.Errorf("%w: 资产编号 %q 已存在", errConflict, id)
1345		}
1346		a := &Asset{ID: id, Name: name, Location: location, Status: statusAvailable}
1347		s.data.Assets = append(s.data.Assets, a)
1348		return a, nil
1349	}
1350	
1351	// report 创建报修工单。返回 (工单, 是否为去重重放, 错误)。
1352	// 所有失败路径都不修改任何业务数据，也不会绑定新的请求标识。
1353	func (s *store) report(assetID, description, requestID string) (*Ticket, bool, error) {
1354		// 已有绑定：相同资产+描述 => 返回原工单（无论其是否已关闭、是否已有新工单）；
1355		// 资产或描述不同 => 拒绝。
1356		if r := s.findRequest(requestID); r != nil {
1357			if r.AssetID != assetID || r.Description != description {
1358				return nil, false, fmt.Errorf(
1359					"%w: 请求标识 %q 已用于资产 %q 的另一笔报修，不能搭配不同的资产编号或故障描述",
1360					errConflict, requestID, r.AssetID)
1361			}
1362			t := s.findTicket(r.TicketID)
1363			if t == nil {
1364				return nil, false, fmt.Errorf("数据内部错误：请求标识 %q 绑定的工单不存在", requestID)
1365			}
1366			return t, true, nil
1367		}
1368	
1369		asset := s.findAsset(assetID)
1370		if asset == nil {
1371			return nil, false, fmt.Errorf("%w: 未知资产编号 %q", errNotFound, assetID)
1372		}
1373		if asset.Status == statusDeactivated {
1374			// 停用期间拒绝新报修，也不绑定新请求标识；恢复使用后可用同一标识重试。
1375			return nil, false, fmt.Errorf("%w: 资产 %s 已停用，不能报修", errConflict, assetID)
1376		}
1377		if t := s.openTicketOf(assetID); t != nil {
1378			return nil, false, fmt.Errorf("%w: 资产 %s 已有未关闭工单 %s", errConflict, assetID, t.ID)
1379		}
1380		// 先确认编号与履历计数器都能推进，再修改任何业务数据：
1381		// 编号耗尽时拒绝新报修，不消耗编号，也不绑定请求标识。
1382		seq := s.data.NextTicketSeq
1383		if seq < 1 || seq == math.MaxInt {
1384			return nil, false, fmt.Errorf("%w: 工单编号计数器已耗尽，无法分配新工单编号", errConflict)
1385		}
1386		eventSeq, err := s.nextEventSeq()
1387		if err != nil {
1388			return nil, false, err
1389		}
1390		t := &Ticket{
1391			ID:          fmt.Sprintf("T%04d", seq),
1392			AssetID:     assetID,
1393			Description: description,
1394			RequestID:   requestID,
1395			Status:      ticketOpen,
1396			CreatedAt:   s.now().Format(time.RFC3339),
1397		}
1398		s.data.NextTicketSeq = seq + 1
1399		s.data.Tickets = append(s.data.Tickets, t)
1400		s.data.Requests = append(s.data.Requests, requestBinding{
1401			RequestID:   requestID,
1402			AssetID:     assetID,
1403			Description: description,
1404			TicketID:    t.ID,
1405		})
1406		asset.Status = statusRepairing
1407		s.appendEvent(eventSeq, assetID, t.ID, eventReport, description, "", "")
1408		return t, false, nil
1409	}
1410	
1411	// closeTicket 关闭未关闭工单并把资产恢复为可用。
1412	// 失败路径不修改任何业务数据。
1413	func (s *store) closeTicket(ticketID, result string) (*Ticket, *Asset, error) {
1414		t := s.findTicket(ticketID)
1415		if t == nil {
1416			return nil, nil, fmt.Errorf("%w: 未知工单编号 %q", errNotFound, ticketID)
1417		}
1418		if t.Status == ticketCancelled {
1419			return nil, nil, fmt.Errorf("%w: 工单 %s 已取消，不能关闭", errConflict, ticketID)
1420		}
1421		if t.Status != ticketOpen {
1422			return nil, nil, fmt.Errorf("%w: 工单 %s 已关闭，不能重复关闭", errConflict, ticketID)
1423		}
1424		asset := s.findAsset(t.AssetID)
1425		if asset == nil {
1426			return nil, nil, fmt.Errorf("数据内部错误：工单 %s 引用的资产不存在", ticketID)
1427		}
1428		eventSeq, err := s.nextEventSeq()
1429		if err != nil {
1430			return nil, nil, err
1431		}
1432		t.Status = ticketClosed
1433		t.Result = result
1434		t.ClosedAt = s.now().Format(time.RFC3339)
1435		asset.Status = statusAvailable
1436		s.appendEvent(eventSeq, asset.ID, t.ID, eventClose, result, "", "")
1437		return t, asset, nil
1438	}
1439	
1440	// cancelTicket 取消未关闭工单并把资产恢复为可用。取消是终态，但不代表维修完成：
1441	// 不填写维修结果，不删除工单、履历或请求绑定，工单编号不回退也不复用。
1442	// 失败路径不修改任何业务数据。
1443	func (s *store) cancelTicket(ticketID, reason string) (*Ticket, *Asset, error) {
1444		t := s.findTicket(ticketID)
1445		if t == nil {
1446			return nil, nil, fmt.Errorf("%w: 未知工单编号 %q", errNotFound, ticketID)
1447		}
1448		if t.Status == ticketCancelled {
1449			return nil, nil, fmt.Errorf("%w: 工单 %s 已取消，不能再次取消", errConflict, ticketID)
1450		}
1451		if t.Status == ticketClosed {
1452			return nil, nil, fmt.Errorf("%w: 工单 %s 已关闭，不能取消", errConflict, ticketID)
1453		}
1454		asset := s.findAsset(t.AssetID)
1455		if asset == nil {
1456			return nil, nil, fmt.Errorf("数据内部错误：工单 %s 引用的资产不存在", ticketID)
1457		}
1458		eventSeq, err := s.nextEventSeq()
1459		if err != nil {
1460			return nil, nil, err
1461		}
1462		t.Status = ticketCancelled
1463		t.CancelReason = reason
1464		t.CancelledAt = s.now().Format(time.RFC3339)
1465		asset.Status = statusAvailable
1466		s.appendEvent(eventSeq, asset.ID, t.ID, eventCancel, reason, "", "")
1467		return t, asset, nil
1468	}
1469	
1470	// assignTicket 为未关闭工单派工或转派：没有负责人时首次派工，已有负责人时
1471	// 转派给不同人员。人员标识只是本地文本记录，不对应任何人员账户。
1472	// 成功后保存负责人、变更时间与说明，并追加一条含原负责人（首次派工为空，
1473	// 展示为“未派工”）、新负责人及说明的派工履历。派工不创建工单、不消耗工单
1474	// 编号，也不改变资产状态或报修请求绑定。失败路径不修改任何业务数据。
1475	func (s *store) assignTicket(ticketID, assignee, note string) (*Ticket, error) {
1476		t := s.findTicket(ticketID)
1477		if t == nil {
1478			return nil, fmt.Errorf("%w: 未知工单编号 %q", errNotFound, ticketID)
1479		}
1480		if t.Status == ticketClosed {
1481			return nil, fmt.Errorf("%w: 工单 %s 已关闭，不能派工", errConflict, ticketID)
1482		}
1483		if t.Status == ticketCancelled {
1484			return nil, fmt.Errorf("%w: 工单 %s 已取消，不能派工", errConflict, ticketID)
1485		}
1486		if assignee == "" {
1487			return nil, fmt.Errorf("%w: 维修人员标识不能为空", errConflict)
1488		}
1489		if note == "" {
1490			return nil, fmt.Errorf("%w: 派工说明不能为空", errConflict)
1491		}
1492		if t.Assignee == assignee {
1493			return nil, fmt.Errorf("%w: 工单 %s 当前负责人已是 %s，不能重复派给同一人",
1494				errConflict, ticketID, assignee)
1495		}
1496		eventSeq, err := s.nextEventSeq()
1497		if err != nil {
1498			return nil, err
1499		}
1500		s.appendEvent(eventSeq, t.AssetID, t.ID, eventAssign, note, t.Assignee, assignee)
1501		t.Assignee = assignee
1502		t.AssignedAt = s.now().Format(time.RFC3339)
1503		t.AssignNote = note
1504		return t, nil
1505	}
1506

