	fmt.Fprintf(w, "资产 %s 已完成周期 %s 的保养。\n", p.AssetID, due)
	fmt.Fprintf(w, "实际完成日: %s\n", done)
	fmt.Fprintf(w, "完成履历序号: %d\n", seq)
	fmt.Fprintf(w, "下一到期日: %s\n", next)
	return nil
