158	// 跨段撤销：调整开启新方案段后，旧段完成不能再撤销；当前段可连续撤销，
159	// 恢复目标完成的周期到期日；同周期重新完成生成新序号，旧序号不能误撤销新完成。
160	func TestAdjustSegmentRevoke(t *testing.T) {
161		s := newTestStore(t)
162		if _, err := s.registerAsset("EQ-1", "打印机", "一楼"); err != nil {
163			t.Fatal(err)
164		}
165		if _, err := s.createPlan("EQ-1", "更换滤芯", "2026-01-01", 30); err != nil {
166			t.Fatal(err)
167		}
168		_, _, oldSeq, err := s.completePlan("EQ-1", "2026-01-01", "2026-01-02", "旧段完成")
169		if err != nil {
170			t.Fatal(err)
171		}
172		if _, _, err := s.adjustPlan("EQ-1", "更换高效滤芯", "2026-02-01", 60, "方案升级"); err != nil {
173			t.Fatal(err)
174		}
175		// 旧段完成不能再撤销。
176		if _, _, err := s.revokeCompletion("EQ-1", oldSeq, "想撤销旧段"); !errors.Is(err, errConflict) {
177			t.Fatalf("旧段完成应不能撤销，得到 %v", err)
178		}
179		// 当前段完成两次，只能先撤销最新的一次。
180		_, _, seq1, err := s.completePlan("EQ-1", "2026-02-01", "2026-02-03", "第一次")
181		if err != nil {
182			t.Fatal(err)
183		}
184		_, _, seq2, err := s.completePlan("EQ-1", "2026-04-02", "2026-04-05", "第二次")
185		if err != nil {
186			t.Fatal(err)
187		}
