281		}
282		// 完成序号的原、新映射：两条完成，按源顺序重编号。
283		if len(outcome.completions) != 2 ||
284			outcome.completions[0].OldSeq != seq1 || outcome.completions[1].OldSeq != seq2 {
285			t.Fatalf("完成序号映射不对: %+v", outcome.completions)
286		}
287		newSeq1 := outcome.completions[0].NewSeq
288		newSeq2 := outcome.completions[1].NewSeq
289		if newSeq1 == seq1 && newSeq2 == seq2 {
290			t.Fatal("目标已有履历时完成序号应重新编号")
291		}
292	
293		re, err := openStore(dstDir)
294		if err != nil {
295			t.Fatal(err)
296		}
297		// 撤销状态与下一到期日保持；撤销引用已替换为新序号。
298		if got := re.findPlan("EQ-A"); got == nil || got.NextDue != "2026-01-11" {
