578	// maintain 显示完成履历序号；history 显示各次完成的序号及有效或已撤销状态；
579	// 参数错误退出码 2，业务失败退出码 1。
580	func TestUnmaintainCommandAndExitCodes(t *testing.T) {
581		dir := t.TempDir()
582		var out, errOut bytes.Buffer
583		runOK := func(args ...string) string {
