// （指明“履历矛盾”类别）；调用方拒绝查询与写入并保留原文件。
func maintValidateError(err error) error {
	var re *maintRuleError
	if !errors.As(err, &re) {
		return err
	}
	switch re.code {
	case ruleDuplicateCreate:
		return fmt.Errorf("履历矛盾：资产 %s 有多条保养建立履历", re.assetID)
	case ruleBeforeCreate:
