	case ruleAdjustScheme:
		return fmt.Errorf("履历矛盾：保养调整履历（序号 %d）记录的原方案与资产 %s 当时的方案不符", re.seq, re.assetID)
	case ruleAdjustNextDue:
		return fmt.Errorf("履历矛盾：保养调整履历（序号 %d）记录的原下一到期日 %s 与当时的下一到期日 %s 不符", re.seq, re.dateA, re.dateB)
	case ruleAdjustFirstDue:
		return fmt.Errorf("履历矛盾：保养调整履历（序号 %d）的新首次到期日 %s 未严格晚于未撤销完成（序号 %d）的实际完成日 %s", re.seq, re.dateA, re.doneSeq, re.dateB)
	case ruleRevokeOldSegment:
		return fmt.Errorf("履历矛盾：保养撤销履历（序号 %d）的目标序号 %d 属于资产 %s 调整前的旧方案段，旧段完成不能再撤销", re.seq, re.target, re.assetID)
	case ruleRevokeUnknown:
		return fmt.Errorf("履历矛盾：保养撤销履历（序号 %d）的目标序号 %d 不是资产 %s 先前的完成履历", re.seq, re.target, re.assetID)
	case ruleRevokeDuplicate:
		return fmt.Errorf("履历矛盾：完成履历序号 %d 被重复撤销（撤销履历序号 %d）", re.target, re.seq)
	case ruleRevokeNotLatest:
		return fmt.Errorf("履历矛盾：保养撤销履历（序号 %d）的目标序号 %d 不是当时最新的有效完成（序号 %d）", re.seq, re.target, re.latest)
	case ruleDoneDeactivated:
		return fmt.Errorf("履历矛盾：资产 %s 在停用期间出现保养完成履历（序号 %d）", re.assetID, re.seq)
	case ruleDueMismatch:
		return fmt.Errorf("履历矛盾：资产 %s 的保养完成履历（序号 %d）周期到期日 %s 与当前下一到期日 %s 不接续", re.assetID, re.seq, re.dateA, re.dateB)
	case ruleDoneBeforeDue:
		return fmt.Errorf("履历矛盾：资产 %s 的保养完成履历（序号 %d）完成日 %s 早于周期到期日 %s", re.assetID, re.seq, re.dateA, re.dateB)
	case ruleNextOverflow:
